INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (6, 2, 3, 2, 'İş Sağlığı ve Güvenliği Esasları ve Laboratuvarda Uyulması Gereken Kurallar | Birim sistemleri ve Vektörler | Bir Boyutta Hareket | İki Boyutta Hareket | Newton’un Hareket Yasaları | Newton’un Hareket Yasalarının Uygulamaları | İş ve Kinetik Enerji | Potansiyel Enerji ve Mekanik Enerjinin Korunumu | Uygulama | Doğrusal Momentum ve Çarpışmalar | Statik Denge ve Moment | Katı Cisimlerin Dönme Hareketi | Katı Cisimlerin Dönme Hareketi | Maddenin Özellikleri', 'Physıcs I', 'FIRST', 'ENGLISH', 'FALL');
INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (6, 0, 4, 3, 'Kümeler. Sayı Kümeleri. Denklemler. Özdeşlikler. Eşitsizlikler. | Fonksiyon kavramı. Fonksiyon çeşitler (Polinom fonksiyon, rasyonel fonksiyon, köklü fonksiyon, üstel ve logaritma fonksiyonu ve bu fonksiyonların en geniş tanım kümeleri). | Fonksiyon çeşitleri (Trigonometrik, ters trigonometrik ve hiperbolik fonksiyonlar.) Parçalı fonksiyonlar, özel tanımlı (Mutlak değer, tam değer, işaret) fonksiyonları. | Limit kavramı ve limit tanımı ile limit hesabı. Limit hesabı için kullanılan teoremlerin ispatı. Sandviç teoremi. Trigonometrik fonksiyonların limitleri. | Sağ ve sol taraflı limitler. Belirsiz haller (0/0,sonsuz/sonsuz, 0.sonsuz, sonsuz-sonsuz,1^sonsuz). | Fonksiyonlarda süreklilik kavramı. Süreksizlik çeşitleri. Sürekli fonksiyonların özellikleri (maksimum ve minimum degerler.) | Türev kavramı ve türev tanımı ile türev hesabı. Türev tanımı ile türev alma kurallarının ispatı. Ters fonksiyonun türevi. | Trigonometrik ve ters trigonometrik fonksiyonların türevi. Üstel ve logaritma fonksiyonlarının türevi. Hiperbolik ve ters hiperbolik fonksiyonların türevi.Parametrik denklemleri verilen fonksiyonların türevleri. Kapalı fonksiyonların türevi. | Yüksek mertebeden türev. Leibniz kuralı ile yüksek mertebeden türev. Kapalı Türev. | Teğet ve normal denklemi. | Artan ve azalan fonksiyonlar. Belirsiz Haller (L’Hopital Kuralı ile incelenmesi). | Fonksiyonların maksimum ve minimumu, asimptotlar. | Eğri çizimleri. | Diferansiyel ile yaklaşık hesap. Maksimum minimum problemleri. Mühendislik problemleri.', 'Mathematıcs I', 'FIRST', 'ENGLISH', 'FALL');
INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (4, 0, 3, 4, 'Lineer denklem sistemlerine giriş | Vektor denklemleri. Ax=b matrix sistemleri. Eselon ve satıra eselon formlar. | Gauss ve Gauss-Jordan Yok Etme Metodları. | Matrislerde islemler ve islemlerin özellikleri. | Lineer sistemler teorisi, homojen ve homojen olmayan sistemler, rank. | Bir matrisin tersi ve terslenebilir matrislerin karakterizasyonu. | LU ayrisimi. Bir matrisin determinanti. Determinant ve elementer satir/sutun islemleri. Determinantin özellikleri. | Determinantin uygulamalari ve Cramer''s kuralı. | Vektorler, lineer bagimsizlik, taban ve donusumler. | Skaler carpim, orthonormal tabanlar, Gram-Schmidt Metodu, QR ayrisimi. | Ozdegerler ve ozvektorler | Karakteristik polinom ve Cayley-Hamilton Teoremi. | Benzer matrisler ve kosegenlestirme. | Lineer sistemlerin davranislari ve özdeğerler/ozvektorler.', 'Lineer Cebir', 'FIRST', 'ENGLISH', 'FALL');
INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (5, 2, 2, 5, 'Ders Tanıtımı & Giriş | Yazılım Mühendisliği Yaşam Döngüsü ve Algoritma Kavramı | Algoritma ve Sözde Kod Yazma | Akış Diyagramı | Programlama ve Programlama Dili Kavramı | Yapısal Programlama Kavramı | Değişken Kavramı, Karar Yapıları, İterasyonlar, Döngüler | Yıl İçi Sınavı | Diziler (Sayı ve Karakter Dizileri) | Alt Yordam Kavramı | Alt Yordam Kavramı | İşaretçiler ve Dinamik Hafıza Yönetimi | Nesneye Dayalı Programlama | Dosyalarda Giriş/Çıkış İşlemleri', 'Yazılım Mühendisliğinde Problem Çözümleme', 'FIRST', 'ENGLISH', 'FALL');
INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (5, 0, 3, 6, 'Bölümün ve yazılım mühendisliğinin tanıtımı, oryantasyon. | Bilgisayarın donanımsal yapısı ve yazılım. Programlama temelleri, yazılım yaşam döngüsü. | Programlama dilleri ve program geliştirme ortamları: Editörler, derleyiciler ve hata ayıklayıcılar. | Versiyon kontrol sistemleri: GIT. | Algoritmalar. | Yazılım mühendisliğinde etik değerler. | İşletim sistemleri ve bilgisayar ağları. | Sorgu dilleri ve veri tabanı sistemleri. | Görü temelli sistemler, görüntü işleme. | Web tabanlı dağıtık bilgi sistemleri. | Web ve mobil uygulama geliştirme platformları, örnek uygulamalar. | Büyük veri ve yapay zeka. | Yazılım geliştirme süreç yönetim temelleri (DevOps). | Örnek yazılım sistemlerinin veya uygulamaların sunumları.', 'Yazılım Mühendisliğine Giriş', 'FIRST', 'ENGLISH', 'FALL');
