INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (4, 0, 3, 20, 'Giriş, Dil Tasarımı Kavramları | Programlama Dillerin Tarihçesi | Sözdizimi ve Semantiği Tanımlama | Sözlüksel ve Sözdizimi Analizi | Adlar, Bağlantılar ve Kapsam | İsim uzayı ve veri tipleri | İfadeler ve Atama İfadeleri | İfade Düzeyinde Kontrol Yapıları | Alt Programlar | Soyut Veri Tipleri ve Kapsülleme Yapısı | Nesneye Yönelik Programlama | Programlama dillerinde hata yakalama | Programlama dillerinde eşzamanlılık | Yorumlamalı Diller ve Python', 'Programlama Dillerinin Prensipleri', 'SECOND', 'ENGLISH', 'SPRING');
INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (6, 0, 4, 9, 'Belirsiz integral. Belirsiz integral alma kuralları. Değişken değiştirme yöntemi. | Kısmi integrasyon yöntemi. Rasyonel fonksiyonların integrali. | Trigonometrik ifadelerin integrali. Trigonometrik dönüşümler. | Binom integrali. Çeşitli değişken değiştirmeler. | Belirli integral kavramı. Aralığın bölüntüsü, Riemann toplamı ve belirli integral tanımı. | Belirli integralin tanım kullanılarak hesabı. Temel integral alma kurallarının ispatı. | İntegral hesabının temel teoremleri. Belirli integralde değişken değiştirme yöntemi. | Belirli integralde kısmi integrasyon yöntemi. Bazı özel tanımlı fonksiyonların belirli integrali. | Belirli integral kullanarak alan hesabı. | Belirli integral kullanarak hacim hesabı. Disk metodu. | Belirli integral kullanarak hacim hesabı. Silindirik tabakalar metodu. | Eğri yayının uzunluğu. Dönel cisimlerin yüzey alanı. | Has Olmayan (Genelleştirilmiş) integraller. | Has Olmayan integral yardımı ile alan ve hacim hesabı.', 'Mathematıcs II', 'FIRST', 'ENGLISH', 'SPRING');
