INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (4, 0, 4, 13, 'Atatürk İlkeleri ve İnkılap Tarihinin içeriği ve amacı - Yenilik ve benzeri kavramlar | Osmanlı Devletinin yapısı ve çözülme sebepleri - Devleti kurtarma ve reform çabaları | Osmanlı Devlet''inde Meşruti gelişmeler ve entelektüel hareketler - Osmanlı Devletinin jeopolitiği ve ona karşı dış politika | İttihat ve Terakki Partisi´nin yönetimi ve devletin son aşaması - 1. Dünya Savaşı ve Osmanlı Devleti | Mondros Mütarekesi ve ona bağlı işgaller, Osmanlı''dan toprak istekleri ve Paris Barış Konferansı - Türk milletinin bağımsızlık için kararlılığı ve Mustafa Kemal Paşa | Mustafa Kemal Paşa''nın fikirleri ve Anadolu''ya geçişi - Kongreler Dönemi (Amasya Görüşmesi, Erzurum ve Sivas Kongreleri) | İstanbul''un İşgali, Türk halkının tepkisi ve diğer önemli gelişmeler - Türkiye Büyük Millet Meclisi''nin açılışı ve özellikleri | Meclisin ilk faaliyetleri ve ilk kanunlar - Meclise tepkiler, dahili isyanlar, karşıt topluluklar, Milli mücadelede basın | ARA SINAV | Milli Mücadelede cepheler, güney ve güneydoğu cephesi - Milli Mücadelede cepheler, doğu cephesi ve Ermeni sorunu | Milli Mücadelede cepheler, Batı cephesi, İlk işgaller ve milli ordular - Düzenli ordunun kuruluşu ve milli mücadelenin finansal kaynakları | Sevr Anlaşması ve Türk milleti üzerindeki etkisi - Milli Mücadelede cepheler, İnönü I, İnönü II, Sakarya Savaşları ve Büyük Taarruz | Milli Mücadelenin siyasi tarafı, Mudanya Ateşkesi ve Lozan Barış Anlaşması, Atatürk dönemi Türk dış politikası - Siyaset, eğitim, kültür, hukuk ve sosyal alanlarda devrimler | Atatürk İlkeleri (Cumhuriyetçilik, Milliyetçilik, Halkçılık) - Atatürk İlkeleri (Laiklik, Devletçilik, Devrimcilik)', 'Atatürk İlkeleri ve İnkılâp Tarihi', 'SECOND', 'TURKISH', 'FALL');
