INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (5, 0, 3, 23, 'Dersin işleyişi, bilgi ve yönetim sistemlerinin mimari yapıları | Veritabanı sunucuları, SQL, veritabanı erişim örnekleri (JDBC, ODBC), soket bağlantısı, veritabanı tasarım prensipleri | Form tabanlı sistemlerin genel özellikleri, İstemci-sunucu (iki iskeleli) mimari uygulama geliştirme (JavaFx). | HTTP protokolü ve protokolün desteklediği metotlar. REST mimarisi ve MVC tasarım deseni | Nesnelerin veritabanına haritalanması: ORM (Object Relational Mapping) | Model-View-Controller tasarım deseni, veritabanı önce yaklaşımı | Kod önce yaklaşımı, Bootstrap CSS framework ile entegrasyon | Web güvenliği: Authentication ve authorization | Cookie temelli güvenlik uygulamaları, token temelli güvenlik uygulamaları (JWT) | Swagger ile REST API dokümantasyonu ve REST sistemlerde istisna ve hata yönetimi | REST sistemlerde dosya yükleme ve indirme, doküman sunucusu. | REST tabanlı bilgi sistemlerinde PDF, Excel raporların üretilmesi (Jasper Report veya JS Report kullanımı) | Mikroservis mimarilerin temel özellikleri, REST API ile mikroservis uygulama geliştirme (Feing client) | Proje çalışmalarının sunulması', 'Dağıtık Bilgi ve Yönetim Sistemleri', 'SECOND', 'ENGLISH', 'SPRING');
