INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (5, 0, 3, 27, 'Büyük veriye giriş, temel bilgiler, data visualization | R ile veri analizi ve modelleme | Makine öğrenmesi: doğrusal regresyon, kümeleme ve sınıflandırma | Hadoop mimari özellikleri, HDFS dağıtık dosyalama sistemi, MapReduce programlama modeli | Apache-Yarn resource manager | Apache-Spark mimari özellikleri ve Spark ile dağıtık paralel hesaplama | Apache-Cassandra ile NoSQL uygulamaları, CAP ile ACID karşılaştırma | Spark-Cassandra ile web tabanlı uygulama geliştirme | Apache Kafka mimarisi, kurulumu ve uygulama geliştirme | Data pipeline uygulaması: Kafka-Spark-Cassandra | Apache-HBase mimari özellikleri ve NoSQL uygulamlar, Cassandra ile kıyaslama | Data warehousing ve ETL, Apache Hive | Apache NiFi, APache Sqoop data warehousing | Apache Flume ile sosyal medya uygulamalarından data çekme uygulamaları', 'Büyük Veri', 'THIRD', 'ENGLISH', 'FALL');
INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (5, 0, 3, 28, 'Bilgisayar ağlarına giriş | İnternet ve OSI modeli | Fiziksel ve veri katmanı | Ağ katmanı | IP protokolü | Yönlendirme algoritmaları | Taşıma katmanı (TCP, UDP) | Taşıma katmanı (tıkanıklık kontrolü) | Uygulama katmanı seviyesi protokoller | Ağ paketi yakalama | libpcap ile paket yakalama projesi | Socket programlama | Socket programlama | VOIP, multimedia, video', 'Bilgisayar Ağları', 'THIRD', 'ENGLISH', 'FALL');
INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (5, 0, 3, 29, 'Sistem yazılımlarında C dili kullanımı, yaygın olarak kullanılan yöntemler (conventions). | Program derleme ve bağlama (link) işlemleri. Makefile oluşturma. Hazır kütüphanelerin kullanımı. | Sistem çağrıları ve C kütüphaneleri ile performans karşılaştırmaları. | Dosya sistemleri, kısayol (link) ve dizin dosyaları. | Yaygın kullanılan sistem çağrıları ile uygulama geliştirme (stat, opendir, readdir/closedir kullanımı). | Diğer sistem çağrılarının analizi ve uygulamalarda kullanımı. | Kabuk programlama (shell programming) ve yeniden yönlendirme (redirection). | Sinyaller (signals), fork ve exec çağrılarının kullanımı | Simgesel dilde programlama - 1 (assembler): Giriş ve lokal değişkenler | Simgesel dilde programlama - 2 (assembler): Alt programlar (procedures) ve saklayıcı kopyalama (register spilling) | Simgesel dilde programlama - 3 (assembler): Adres değişkenleri (pointers) | Simgesel dilde programlama - 4 (assembler): Dallanma ve koşullu dallanma | Paralel programlama (Threads) | Paralel programlama: Sunucu istemci modelinde programlama', 'Sistem Programlama', 'THIRD', 'ENGLISH', 'FALL');
INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (5, 0, 3, 30, 'Tasarım Desenlerine Giriş | Tasarım Desenlerine Giriş | Yaratımsal Tasarım Desenleri | Yaratımsal Tasarım Desenleri | Yaratımsal Tasarım Desenleri | Yapısal Tasarım Desenleri | Yapısal Tasarım Desenleri | Yapısal Tasarım Desenleri | Davranışsal Tasarım Desenleri | Davranışsal Tasarım Desenleri | Davranışsal Tasarım Desenleri | Reaktif ve Eş Zamanlı Desenler | Reaktif ve Eş Zamanlı Desenler | Deyimler ve Anti Desenler', 'Tasarım Desenleri', 'THIRD', 'ENGLISH', 'FALL');
INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (5, 0, 3, 31, 'Introduction | Propositional logic | Predicate logic and quantifiers | Hoare Logic, weakest preconditions and strongest postconditions | Recursion and terminations, inductive data types | Lemmas and proofs | List proofs, sorting algorithms | Midterm exam | Abstraction and modules | Invariants for data structures | Loop invariants | Specifications for recursive and iterative Programs | Specifications for Objects | Specifications for Objects', 'Yazılım Mühendisliğinde Biçimsel Yöntemler', 'THIRD', 'ENGLISH', 'SPRING');
INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (6, 0, 3, 32, 'Algoritmalara giriş, ayrık matematik, veri yapıları, asimtotik notasyonlar, algoritma etkinliği | En iyi, en kötü ve ortalama zaman karmaşıklığı analizleri | Brute Force (Kaba Kuvvet) ve Algoritmaları: Selection Sort, Bubble Sort | Alan Karmaşıklığı | Divide and Conquer (Böl ve Yönet) ve Algoritmaları: Özyinelemeli Algoritmalar, Merge Sort, Quick Sort | Decrease and Conquer (Azalt ve Yönet) ve Algoritmaları: Insertion Sort | Dinamik Programlama - Böl ve Yönet: Fibonacci Serisi, Binom Sabitleri | Dinamik Programlama: En Uzun Alt Katar Problemi, Matris Çarpımı | Dinamik Programlama: En Kısa Yol Problemi, Sırt Çantası Problemi | Greedy Approach (Aç Gözlü Yaklaşım): Sırt Çantası Problemi, En Kısa Yol Problemi | Greedy Approach (Aç Gözlü Yaklaşım): Prim, Kruskal Algoritmaları | Transform and Conquer (Dönüştür ve Yönet): Mod Değeri Hesabı | Transform and Conquer (Dönüştür ve Yönet): İkili Ağaçlar, Denge ve AVL Ağaçları, Heap Sort | Hesaplama Teorisi: Hanoi Kuleleri, Karmaşıklık ve Hesaplanabilirlik Teorisi, NP-Tam, P, NP-Hard Problemler', 'Algoritma Analizi ve Tasarımı', 'THIRD', 'ENGLISH', 'SPRING');
