INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (5, 0, 3, 35, 'Yazılım yaşam döngüsü. Yazılım build araçları: Make, Ant, Maven, Gradle, Msbuild vs. | Şelale ve çevik yazılım geliştirme modelleri. DevOps fazları: Plan, code, build, test, integrate, deploy, operate ve monitor. | Versiyon kontrol sistemleri (Git) ve grup halinde yazılım geliştirme. | Bulut sistem ile yazılımların yayınlanması (publish). Basit dosya transferi (FTP) ile yazılım yayınlama. Web sunucusu (Nginx) konfigürasyonu. | Sanallaştırma ve konteyner teknolojileri (Docker). Dockerfile ile yazılımların konteynera konulması. | Konteyner hub kullanımı (Docker-Hub). Konteyner hub (Docker-Hub) üzerinden yazılım dağıtımı. Bulut üzerinde yayınlama. | Docker compose ile çok sayıda konteynerin organizasyonu ve koordinasyonu. | GitHub ile yazılım oluşturma (build) ve akış kontrolu (flow). | Sürekli teslimat (Continuous Delivery). | Sürekli dağıtım (Continuous Deployment). | Jenkins sunucusu ile yazılım yayınlama süreçlerinin otomatikleştirilmesi. Sürekli entegrasyon (Continuous Integration with Jenkins). | Lokal bilgisayarda veya bulut üzerinde Kubernetes küme bilgisayar oluşturma ve konteyner yayınlama. | Bulut üzerinde Kubernetes ile sürekli performans izleme. | Proje çalışmalarının değerlendirilmesi ve tartışma.', 'Yazılım Geliştirme Süreçleri (Devops)', 'THIRD', 'ENGLISH', 'SPRING');
