INSERT INTO public.home_course (ects, practical_hours, theoretical_hours, home_course_id, description, course_name, education_year, language, semester) VALUES (4, 0, 4, 1, 'A. Dersin amacı ve işleyişi, dilin tanımı ve insan hayatındaki yeri B. Konuşma dili ile yazı dili arasındaki farklar. | A. Dilin özellikleri ve dilin yapısını kavrama. Okuma ve anlama yöntemleri B. Noktalama işaretleri | A. Dünya dilleri arasında Türkçe; lehçe, şive ve ağız arasındaki farklar B. Dil-düşünce ilişkisini kavrama, eleştirel düşünme. Noktalama işaretleri | A. Belli başlı Türkçe eserlerin değerlendirilmesi B. Yazım kuralları | A. Örneklerle Türkçenin ses özellikleri B. Kültürün değişen ve değişmeyen unsurları | A. Türkçede sözcük yapısının incelenmesi B. Yazı türlerinden Şiir ve şiir incelemesi C. Yazı için ön hazırlıklar D. Form yazıları: dilekçe, tutanak, rapor... | A. Sözcük Türleri B. Roman ve hikâye türleri. Edebiyatta kurgu-yaşantı ayrımı. C. Sözlük kullanımı | A. Söz öbekleri B. Klasik kurmaca türler C. Ödev, proje hazırlama D. Yazılı ve Görsel Medyada Dil Yanlışları | A. Türkçede cümle yapısı ve cümle türleri B. Kullanmalık Metinler: Tiyatro, senaryo C. Bilimsel yazmanın ilkeleri. Yazmada plan, iyi bir plan nasıl yapılır? | A. Cümle üstü dil yapıları: paragraf ve metin B. İşlevsel Türler: Makale-Eleştiri. Eleştiride yöntem sorunu. C. İletişim kazaları | A. Semantik bilgisi B. İşlevsel Türler: Deneme - Fıkra-Gazete Köşe yazısı-Söyleşi C. Paragraf yazımı; paragraf türleri ve özellikleri | A. Söz sanatları ve Türkçenin söz varlığı B. İşlevsel Türler: Mektup, Gezi Yaazısı, Anı, Günlük.C. Dil Yanlışları (Anlatım Bozuklukları). | A. Türkçenin güncel sorunları B. Diksiyonda dikkat edilmesi gereken noktalar C. Bilimsel yazılar | Genel tekrar', 'Türk Dili', 'FIRST', 'TURKISH', 'FALL');
